/*
 * Premium workspace organisation (library/viewport Checkpoint 2, sidebar revision)
 * - Top: model identity, Studio/Inspect mode, saved views and distraction-free mode.
 * - Left: grouped assembly tree. Centre: model + annotations. Upper-right: orientation.
 * - Bottom: compact tool launcher only. Tool options never float as a horizontal bar;
 *   Inspect, Measure, Section and Display open in the right contextual sidebar.
 * - Right: tool options, model properties and saved views.
 * - Panels collapse, resize and become drawers before they can squeeze the model.
 * - Studio presentation is display-only: source materials and geometry remain immutable.
 */

type Tool = 'inspect' | 'measure' | 'section' | 'display';
type SideTab = 'tool' | 'properties' | 'views';
const TOOLS: { id: Tool; label: string; icon: LucideIcon; key: string; hint: string }[] = [
  { id: 'inspect', label: 'Inspect', icon: MousePointer2, key: 'I', hint: 'Select, focus, hide and isolate components' },
  { id: 'measure', label: 'Measure', icon: Ruler, key: 'M', hint: 'Point-to-point distance on mesh surfaces' },
  { id: 'section', label: 'Section', icon: Scissors, key: 'S', hint: 'Uncapped clipping plane on X, Y or Z' },
  { id: 'display', label: 'Display', icon: Palette, key: 'D', hint: 'Rendering, background, turntable and explosion' },
];

